import{_ as i,a0 as l,w as p,s as d,I as s,x as r,a1 as o,A as a,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"兩種方式創建你自己的 Docker 基本映像 | LCTT x X-CMD","titleTemplate":false,"description":"兩種方式創建你自己的 Docker 基本映像 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"兩種方式創建你自己的 Docker 基本映像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"兩種方式創建你自己的 Docker 基本映像 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150330 2 Ways to Create Your Own Docker Base Image","title":"兩種方式創建你自己的 Docker 基本映像","tag":"201505","desc":""},"relativePath":"201505/20150330 2 Ways to Create Your Own Docker Base Image.md","filePath":"[post].md"}'),u={name:"201505/20150330 2 Ways to Create Your Own Docker Base Image.md"};function m(c,t,k,b,f,D){const e=l("Link");return p(),d("div",null,[t[18]||(t[18]=s("h1",{id:"兩種方式創建你自己的-docker-基本映像",tabindex:"-1"},[r("兩種方式創建你自己的 Docker 基本映像 "),s("a",{class:"header-anchor",href:"#兩種方式創建你自己的-docker-基本映像","aria-label":"Permalink to “兩種方式創建你自己的 Docker 基本映像”"},"​")],-1)),s("p",null,[t[1]||(t[1]=r("歡迎大家，今天我們學習一下 docker 基本映像以及如何構建我們自己的 docker 基本映像。",-1)),o(e,{href:"https://www.docker.com/"},{default:a(()=>[...t[0]||(t[0]=[r("Docker",-1)])]),_:1}),t[2]||(t[2]=r(" 是一個開源項目，提供了一個可以打包、裝載和運行任何應用的輕量級容器的開放平台。它沒有語言支持、框架和打包系統的限制，從小型的家用電腦到高端服務器，在何時何地都可以運行。這使它們可以不依賴於特定軟件棧和供應商，像一塊塊積木一樣部署和擴展網絡應用、資料庫和後端服務。",-1))]),t[19]||(t[19]=n(`<p>Docker 映像是不可更改的只讀層。Docker 使用 <strong>Union File System</strong> 在只讀文件系統上增加可讀寫的文件系統，但所有更改都發生在最頂層的可寫層，而其下的只讀映像上的原始文件仍然不會改變。由於映像不會改變，也就沒有狀態。基本映像是沒有父類的那些映像。Docker 基本映像主要的好處是它允許我們有一個獨立運行的 Linux 操作系統。</p><p>下面是我們如何可以創建自定義的基本映像的方式。</p><h3 id="_1-使用-tar-創建-docker-基本映像" tabindex="-1">1. 使用 Tar 創建 Docker 基本映像 <a class="header-anchor" href="#_1-使用-tar-創建-docker-基本映像" aria-label="Permalink to “1. 使用 Tar 創建 Docker 基本映像”">​</a></h3><p>我們可以使用 tar 構建我們自己的基本映像，我們從一個運行中的 Linux 發行版開始，將其打包為基本映像。這過程可能會有些不同，它取決於我們打算構建的發行版。在 Debian 發行版中，已經預帶了 debootstrap。在開始下面的步驟之前，我們需要安裝 debootstrap。debootstrap 用來獲取構建基本系統需要的包。這裏，我們構建基於 Ubuntu 14.04 &quot;Trusty&quot; 的映像。要完成這些，我們需要在終端或者 shell 中運行以下命令。</p><pre><code>$ sudo debootstrap trusty trusty &gt; /dev/null
$ sudo tar -C trusty -c . | sudo docker import - trusty
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/creating-base-image-debootstrap.png" alt="使用debootstrap構建docker基本映像"></p><p>上面的命令為當前文件夾創建了一個 tar 文件並輸出到標準輸出中，&quot;docker import - trusty&quot; 通過管道從標準輸入中獲取這個 tar 文件並根據它創建一個名為 trusty 的基本映像。然後，如下所示，我們將運行映像內部的一條測試命令。</p><pre><code>$  docker run trusty cat /etc/lsb-release
</code></pre>`,8)),s("p",null,[o(e,{href:"https://github.com/docker/docker/blob/master/contrib/mkimage-busybox.sh"},{default:a(()=>[...t[3]||(t[3]=[r("Docker GitHub Repo",-1)])]),_:1}),t[4]||(t[4]=r(" 中有一些允許我們快速構建基本映像的事例腳本.",-1))]),t[20]||(t[20]=n(`<h3 id="_2-使用scratch構建基本映像" tabindex="-1">2. 使用Scratch構建基本映像 <a class="header-anchor" href="#_2-使用scratch構建基本映像" aria-label="Permalink to “2. 使用Scratch構建基本映像”">​</a></h3><p>在 Docker registry 中，有一個被稱為 Scratch 的使用空 tar 文件構建的特殊庫：</p><pre><code>$ tar cv --files-from /dev/null | docker import - scratch
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/creating-base-image-using-scratch.png" alt="使用scratch構建docker基本映像"></p><p>我們可以使用這個映像構建新的小容器：</p><pre><code>FROM scratch
ADD script.sh /usr/local/bin/run.sh
CMD [&quot;/usr/local/bin/run.sh&quot;]
</code></pre><p>上面的 Dockerfile 文件來自一個很小的映像。這裏，它首先從一個完全空的文件系統開始，然後它複製新建的 /usr/local/bin/run.sh 為 script.sh ，然後運行腳本 /usr/local/bin/run.sh。</p><h3 id="結尾" tabindex="-1">結尾 <a class="header-anchor" href="#結尾" aria-label="Permalink to “結尾”">​</a></h3><p>這這個教程中，我們學習瞭如何構建一個開箱即用的自定義 Docker 基本映像。構建一個 docker 基本映像是一個很簡單的任務，因為這裏有很多已經可用的包和腳本。如果我們想要在裏面安裝想要的東西，構建 docker 基本映像非常有用。如果有任何疑問，建議或者反饋，請在下面的評論框中寫下來。非常感謝！享受吧 😃</p><hr>`,10)),s("p",null,[t[6]||(t[6]=r("via: ",-1)),o(e,{href:"http://linoxide.com/linux-how-to/2-ways-create-docker-base-image/"},{default:a(()=>[...t[5]||(t[5]=[r("http://linoxide.com/linux-how-to/2-ways-create-docker-base-image/",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=r("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:a(()=>[...t[7]||(t[7]=[r("Arun Pyasi",-1)])]),_:1}),t[11]||(t[11]=r(" 譯者：",-1)),o(e,{href:"https://github.com/ictlyh"},{default:a(()=>[...t[8]||(t[8]=[r("ictlyh",-1)])]),_:1}),t[12]||(t[12]=r(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[r("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=r("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[r("LCTT",-1)])]),_:1}),t[16]||(t[16]=r(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[r("Linux中國",-1)])]),_:1}),t[17]||(t[17]=r(" 榮譽推出",-1))])])}const x=i(u,[["render",m]]);export{h as __pageData,x as default};
